with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,11,'______ feeling exhausted, she continued studying.','["Although","Despite of","Even though","Despite"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'Despite + gerundio o sustantivo; despite of es incorrecto.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,12,'______ he had very little experience, he got the job.','["Although","Despite","In spite of","However"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'Although introduce una oración con sujeto y verbo.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,13,'My sister loves living in the countryside, ______ I prefer the city.','["despite","whereas","in spite of","nevertheless"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'Whereas contrasta dos situaciones en una misma oración.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,14,'I look forward to ______ from you soon.','["hear","to hear","hearing","heard"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'Look forward to + gerundio: to es preposición.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,15,'The police have ______ the stolen jewellery.','["found","find","founded","finding"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'Find–found–found: después de have va el participio.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,16,'A person who sees a crime take place is called a ______.','["suspect","victim","detective","witness"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'Witness es la persona que presencia un hecho.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,17,'When did Emma discover that her laptop was missing?','["On Sunday evening","On Monday","Two days after the police investigation","On Friday"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'El texto dice Last Monday.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,18,'What helped the police investigate the theft?','["Emma''s cloud backups","A confession from the stranger","Fingerprints and a colleague''s account","A clear security video"]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'Se utilizaron huellas y el testimonio de un compañero.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,19,'Why was Emma particularly worried about losing her laptop?','["She hadn''t backed up her files recently.","She had bought it that morning.","It belonged to her colleague.","She had forgotten her password."]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'No había hecho copias de seguridad en varias semanas.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,20,'What new habit has Emma developed since the incident?','["She leaves her laptop at the office.","She checks the security cameras every day.","She avoids working in the evening.","She saves her work to the cloud every evening."]'::jsonb,null from public.examenes where codigo='EE-2026-10-09-001' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'Ahora guarda su trabajo cada tarde en la nube.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
insert into public.examenes(codigo,titulo,fecha,nivel,descripcion,publicado) values('EE-2026-10-10-002','Examen diario 002','2026-10-10','B1-B2','20 preguntas',true) on conflict(codigo) do update set titulo=excluded.titulo,publicado=true;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,1,'I ______ here since 2022.','["lived","have lived","had live","live"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-presente-en-ingles.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Past Simple no expresa una situación que continúa hasta hoy.
B) Present Perfect con since expresa continuidad desde 2022 hasta ahora.
C) Had live es gramaticalmente incorrecto: habría que usar had lived, y requeriría otro punto pasado.
D) Present Simple no combina naturalmente con since para esta duración.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,2,'At 8 p.m. yesterday, I ______ TV.','["have watched","watch","was watching","had watching"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-pasado-en-ingles.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Present Perfect no se utiliza con yesterday, tiempo pasado terminado.
B) Present Simple describe hábitos, no una acción en progreso ayer a esa hora.
C) Past Continuous expresa una acción que estaba ocurriendo a una hora concreta del pasado.
D) Had watching no es una estructura válida; el Past Perfect sería had watched.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,3,'By next Friday, I ______ the report.','["will have finish","have finish","will be finished the report","will have finished"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-futuro-en-ingles.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Future Perfect exige participio finished, no finish.
B) Present Perfect necesita el participio finished y no señala finalización antes del próximo viernes.
C) La construcción pasiva necesitaría the report como sujeto: the report will be finished.
D) Future Perfect: will have + participio, para una acción completada antes de un momento futuro.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,4,'When I was a child, I ______ shy, but I''m confident now.','["used to be","am used to be","used to being","use to be"]'::jsonb,'https://jnfz92.github.io/post/used-to-would-be-used-to-get-used-to.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Used to be describe un estado habitual del pasado que ya no es cierto.
B) Be used to exige sustantivo o -ing, y am expresa presente.
C) Used to para hábitos pasados exige infinitivo be, no being.
D) En afirmativa se escribe used to, no use to.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,5,'She''s used to ______ early.','["wake up","woke up","waking up","wakes up"]'::jsonb,'https://jnfz92.github.io/post/used-to-would-be-used-to-get-used-to.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Be used to va seguido de nombre o gerundio, no infinitivo.
B) Woke up es pasado, no gerundio.
C) Waking up es gerundio tras la preposición to de be used to.
D) Wakes up es forma verbal finita, no gerundio.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,6,'Did you ______ to play tennis when you were younger?','["used","use","using","uses"]'::jsonb,'https://jnfz92.github.io/post/used-to-would-be-used-to-get-used-to.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Con did el verbo vuelve a forma base: use.
B) Did + sujeto + use to es la interrogativa correcta.
C) Using no puede seguir a did como verbo principal.
D) Uses corresponde a tercera persona singular presente, no a did.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,7,'______ the rain, we went for a walk.','["Although","Despite of","Even though","Despite"]'::jsonb,'https://jnfz92.github.io/post/despite-vs-in-spite-of.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Although introduce oración (although it rained), no solo sintagma nominal.
B) Despite of es incorrecto: se usa despite o in spite of.
C) Even though exige una oración con verbo.
D) Despite puede ir seguido directamente de the rain.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,8,'______ she was tired, she finished her homework.','["Although","Despite","In spite of","Despite of"]'::jsonb,'https://jnfz92.github.io/post/linking-words-of-contrast.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Although introduce la oración completa she was tired.
B) Despite requiere un sustantivo o forma -ing: despite being tired.
C) In spite of requiere sintagma nominal o -ing, no she was tired.
D) Despite of no es una construcción inglesa correcta.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,9,'He prefers tea, ______ I prefer coffee.','["despite","however","whereas","in spite of"]'::jsonb,'https://jnfz92.github.io/post/linking-words-of-contrast.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Despite debe acompañar un sustantivo o -ing, no conectar directamente dos cláusulas así.
B) However es un adverbio conjuntivo; requeriría puntuación diferente, por ejemplo punto y coma.
C) Whereas enlaza directamente dos oraciones que contrastan preferencias.
D) In spite of requiere sintagma nominal o -ing.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,10,'¿Cuál es la forma habitual británica del pasado de travel?','["traveld","travelled","travelld","travalled"]'::jsonb,'https://jnfz92.github.io/post/ingles-americano-vs-britanico-diferencias-verbos.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Traveld omite la vocal e de la terminación -ed.
B) Travelled duplica la l en la ortografía británica.
C) Travelld no lleva -ed correctamente.
D) Travalled altera incorrectamente la raíz travel.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,11,'Completa la frase con una forma habitual del inglés americano: She has ______ better.','["get","getting","gets","gotten"]'::jsonb,'https://jnfz92.github.io/post/ingles-americano-vs-britanico-diferencias-verbos.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Después de has se requiere participio, no infinitivo get.
B) Getting es gerundio, no participio del Present Perfect.
C) Gets es tercera persona del presente, no participio.
D) Gotten es participio de get habitual en inglés americano.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,12,'We ______ the bus at the next stop.','["get off","get in","get out","get up"]'::jsonb,'https://jnfz92.github.io/post/phrasal-verbs-with-get.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Get off se usa para bajarse de un autobús o tren.
B) Get in se usa para entrar en vehículos pequeños, como coches.
C) Get out se usa para salir de coches; aquí se dice get off the bus.
D) Get up significa levantarse, no bajarse de un autobús.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,13,'We need ______ information about the project.','["many","several","some","a few"]'::jsonb,'https://jnfz92.github.io/post/countable-uncountable-nouns.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Many acompaña sustantivos contables plurales; information es incontable.
B) Several requiere sustantivo plural contable.
C) Some puede modificar information, un nombre incontable.
D) A few se usa con nombres contables plurales.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,14,'There isn''t ______ traffic today.','["many","much","several","a few"]'::jsonb,'https://jnfz92.github.io/post/countable-uncountable-nouns.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Many necesita un plural contable; traffic es incontable.
B) Much se usa con nombres incontables en negativas.
C) Several requiere sustantivo plural contable.
D) A few se aplica a plurales contables.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,15,'She might ______ late.','["arrives","to arrive","arriving","arrive"]'::jsonb,'https://jnfz92.github.io/post/might.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Tras modal might va forma base sin -s.
B) Los modales no llevan to antes del verbo base.
C) Arriving requiere otra estructura (por ejemplo might be arriving).
D) Might + infinitivo sin to: might arrive.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,16,'I ______ the question and gave the wrong answer.','["misunderstood","disunderstood","ununderstood","inunderstood"]'::jsonb,'https://jnfz92.github.io/post/negative-prefixes.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Misunderstood es el pasado de misunderstand, entender mal.
B) Disunderstood no es una forma estándar en inglés.
C) Ununderstood no es el pasado de misunderstand.
D) Inunderstood no es una forma estándar del verbo.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,17,'Where did Swietenia grow up?','["London","Rome","Pramuka Island","New York"]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) London no es el lugar mencionado en el texto.
B) Rome no aparece como lugar de su infancia.
C) El texto sitúa su infancia en Pramuka Island, Indonesia.
D) New York no aparece en el relato.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,18,'What did she notice when she was thirteen?','["The seabed was covered with rubbish.","There were more fish than ever.","Air pollution had disappeared.","The beaches had become completely clean."]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) El texto afirma que había basura cubriendo el fondo marino.
B) Observó menos vida marina, no más peces.
C) El texto trata de residuos marinos, no de la desaparición de contaminación aérea.
D) Describe deterioro ambiental, no playas completamente limpias.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,19,'What did Swietenia start with two friends?','["A newspaper","A car factory","A language school","A community of divers"]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) No fundó un periódico según el texto.
B) No se menciona ninguna fábrica de coches.
C) No creó una academia de idiomas.
D) Inició una comunidad de buceadores con dos amigos.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,20,'What was one purpose of the group''s workshops?','["To teach people how to repair cars.","To raise awareness of marine waste.","To organise football competitions.","To promote air travel."]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-10-002' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Los talleres no abordaban mecánica del automóvil.
B) Buscaban concienciar sobre los residuos en el mar.
C) No tenían relación con competiciones deportivas.
D) No estaban relacionados con la promoción de viajes aéreos.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
insert into public.examenes(codigo,titulo,fecha,nivel,descripcion,publicado) values('EE-2026-10-11-003','Examen diario 003','2026-10-11','B1-B2','20 preguntas',true) on conflict(codigo) do update set titulo=excluded.titulo,publicado=true;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,1,'Ana said, “I am tired.” Which sentence uses the usual backshift after said?','["Ana said that she had been tired.","Ana said that she was tired.","Ana said that she will be tired.","Ana said that she tired."]'::jsonb,'https://jnfz92.github.io/post/direct-reported-speech.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Past perfect cambia el momento a uno anterior, no es el retroceso habitual de am tired.
B) Was tired es el retroceso habitual de am tired tras said.
C) Will be indica futuro, no el cambio habitual de am.
D) Falta el verbo be; tired es adjetivo.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,2,'Mark said, “I have finished the report.” Which version uses standard backshift?','["Mark said he has finished the report.","Mark said he will finish the report.","Mark said he had finished the report.","Mark said he have finished the report."]'::jsonb,'https://jnfz92.github.io/post/direct-reported-speech.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Has finished mantiene el presente perfecto sin retroceso, aunque puede conservarse si sigue siendo actual; aquí piden backshift.
B) Will finish cambia el significado a futuro.
C) Had finished es el retroceso habitual de have finished.
D) He have es incorrecto: tercera persona requiere has, o had para backshift.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,3,'Luis said, “I saw him yesterday.” Report this the following day.','["Luis said that he had seen him the day before.","Luis said that he sees him tomorrow.","Luis said that he has seen him yesterday.","Luis said that he had saw him the day before."]'::jsonb,'https://jnfz92.github.io/post/direct-reported-speech.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Had seen y the day before son los cambios esperados de saw y yesterday.
B) Sees y tomorrow cambian indebidamente tiempo y referencia.
C) Has seen no aplica el retroceso y conserva yesterday.
D) El participio de see es seen, nunca saw después de had.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,4,'Which sentence naturally describes knowing an answer?','["I''m knowing the answer.","I am know the answer.","I knowing the answer.","I know the answer."]'::jsonb,'https://jnfz92.github.io/post/stative-verbs.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Know expresa estado y normalmente no admite progresivo.
B) Am know carece de -ing.
C) Falta el auxiliar am y la construcción no es natural para know.
D) I know expresa un estado actual correctamente.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,5,'Which sentence uses have as a dynamic action?','["I am having a car.","I am having lunch.","I am having two brothers.","I am having an opinion."]'::jsonb,'https://jnfz92.github.io/post/stative-verbs.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Have a car expresa posesión, no acción progresiva.
B) Having lunch es una actividad, por eso admite -ing.
C) Have two brothers expresa relación de familia, no actividad.
D) Have an opinion expresa estado/posesión, no actividad.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,6,'Choose the correct form: She avoids ______ mistakes.','["to make","make","making","made"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Avoid rige gerundio, no to + infinitivo.
B) Avoid no va seguido del infinitivo simple.
C) Avoid making es la construcción correcta.
D) Made es pasado/participio, no gerundio.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,7,'Choose the correct form: We decided ______ English every day.','["to study","studying","study","studied"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Decide va normalmente con to + infinitivo.
B) Studying no corresponde al patrón decide to.
C) Falta to antes de study.
D) Studied no forma complemento correcto después de decided.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,8,'You have NOT called Marta yet. Which reminder is correct?','["Remember calling Marta.","Remember called Marta.","Remember call Marta.","Remember to call Marta."]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Remember calling supone que la llamada ya ocurrió.
B) Called no encaja directamente después de remember.
C) Falta to antes del infinitivo con sentido de tarea futura.
D) Remember to call recuerda hacer algo que aún no se ha hecho.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,9,'How do you say «Nunca he estado en Nueva York»?','["I haven''t never been to New York.","I have never been to New York.","I never have been at New York.","I have never went to New York."]'::jsonb,'https://jnfz92.github.io/post/present-perfect-never-yet.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Have not never duplica negación.
B) Have never been to es el present perfect natural para experiencias.
C) La posición de never y la preposición at son inapropiadas.
D) Después de have se usa been/gone, no went.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,10,'Complete: She ______ finished the assignment ______. (Todavía no ha terminado.)','["has / never","have not / never","hasn''t / yet","has not / already"]'::jsonb,'https://jnfz92.github.io/post/present-perfect-never-yet.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Has never finished no significa simplemente todavía no ha terminado.
B) Have not no concuerda con she.
C) Hasn''t ... yet significa todavía no.
D) Already se usa en otro contexto, normalmente afirmativo o interrogativo; no transmite la frase indicada.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,11,'Which response politely disagrees while acknowledging another person''s point?','["I see your point, but I think there is another factor.","You are wrong and that is all.","Your opinion is ridiculous.","I refuse to hear your argument."]'::jsonb,'https://jnfz92.github.io/post/agreeing-disagreeing.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) I see your point reconoce el argumento y añade desacuerdo cortés.
B) You are wrong es demasiado brusco.
C) Ridiculous es una descalificación.
D) I refuse to hear impide el diálogo, no discrepa cortésmente.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,12,'Which expression is formal and somewhat traditional when disagreeing?','["No way!","You must be joking.","Whatever.","I beg to differ."]'::jsonb,'https://jnfz92.github.io/post/agreeing-disagreeing.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) No way es informal, no formal.
B) You must be joking expresa desacuerdo poco ceremonioso.
C) Whatever es informal y despectivo.
D) I beg to differ es una fórmula formal de desacuerdo.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,13,'Which opinion phrase is informal and especially associated with British/Australian English?','["I hereby certify","I reckon","It is hereby resolved","Pursuant to the above"]'::jsonb,'https://jnfz92.github.io/post/expressing-opinions.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) I hereby certify corresponde a un registro jurídico/formal.
B) I reckon es una expresión informal frecuente en inglés británico y australiano.
C) It is hereby resolved es una fórmula institucional.
D) Pursuant to the above es formal/jurídico.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,14,'What does sewage mean in the environment article?','["Aguas residuales","Energía renovable","Emisiones de vehículos","Contaminación acústica"]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Sewage designa aguas residuales.
B) Renewable energy significa energía renovable.
C) Vehicle emissions se refiere a emisiones de vehículos.
D) Noise pollution significa contaminación acústica.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,15,'Which sentence uses the uncountable noun pollution correctly?','["Pollutions are a problem.","A pollution is a problem.","Many pollutions is a problem.","Pollution is a problem."]'::jsonb,'https://jnfz92.github.io/post/environment-vocabulary.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Pollution suele ser incontable y no se usa como plural genérico.
B) A pollution no es la forma natural para el problema genérico.
C) Many exige contable plural y aquí hay además discordancia de verbo.
D) Pollution is trata pollution como nombre incontable singular.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,16,'Choose the natural instruction for leaving a car.','["Get off the car.","Get out of the car.","Get up the car.","Get in the car."]'::jsonb,'https://jnfz92.github.io/post/phrasal-verbs-with-get.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Get off se usa con autobús o tren, no normalmente con car.
B) Get out of the car significa salir del coche.
C) Get up significa levantarse.
D) Get in significa entrar al coche, opuesto de salir.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,17,'What is the correct negative form of accurate?','["unaccurate","disaccurate","inaccurate","misaccurate"]'::jsonb,'https://jnfz92.github.io/post/negative-prefixes.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Unaccurate no es la forma habitual.
B) Disaccurate no es una palabra normal.
C) Inaccurate es el antónimo correcto de accurate.
D) Misaccurate no es una palabra normal.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,18,'You mean «Normalmente voy al trabajo en tren». Complete: I ______ take the train to work.','["normally","currently","now","at present"]'::jsonb,'https://jnfz92.github.io/post/adverbs-of-frequency.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Normally indica hábito o frecuencia habitual.
B) Currently indica situación actual, no costumbre.
C) Now es puntual y no describe normalmente.
D) At present indica situación actual, no periodicidad habitual.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,19,'Which reading technique helps you understand the GENERAL idea of a text quickly?','["Scanning for a phone number","Reading only a dictionary definition","Skimming the title and first sentences","Looking for one specific date"]'::jsonb,'https://jnfz92.github.io/post/skimming-scanning-reading.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Scanning busca datos específicos, no idea global.
B) Una definición aislada no permite captar un texto.
C) Skimming sirve para captar rápidamente la idea general.
D) Una fecha específica es objetivo de scanning.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,20,'You need to find the YEAR in a long article. Which strategy fits best?','["Read every sentence aloud first.","Translate every adjective.","Memorise the opening paragraph.","Scan for numbers and dates."]'::jsonb,'https://jnfz92.github.io/post/skimming-scanning-reading.html' from public.examenes where codigo='EE-2026-10-11-003' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Leerlo íntegro en voz alta es poco eficiente para localizar un año.
B) Traducir adjetivos no ayuda a localizar fechas.
C) Memorizar el principio no permite encontrar el dato.
D) Scanning busca números y fechas concretas.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
insert into public.examenes(codigo,titulo,fecha,nivel,descripcion,publicado) values('EE-2026-10-12-004','Examen diario 004','2026-10-12','B1-B2','20 preguntas',true) on conflict(codigo) do update set titulo=excluded.titulo,publicado=true;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,1,'Marta said, “I am studying now.” Report her words later.','["She said she studies now.","She said she was studying then.","She said she had study then.","She said she is studying yesterday."]'::jsonb,'https://jnfz92.github.io/post/direct-reported-speech.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) No hay backshift ni cambio de now.
B) Past Continuous y then: correcto.
C) Had study es incorrecto; sería had studied.
D) Presente y yesterday son incompatibles.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,2,'Ben said, “I have written the email.” Report his words.','["He said he had written it.","He said he has wrote it.","He said he was write it.","He said he have written it."]'::jsonb,'https://jnfz92.github.io/post/direct-reported-speech.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Present Perfect pasa a Past Perfect.
B) Has wrote usa participio incorrecto.
C) Was write es incorrecto.
D) He have no concuerda y no retrocede el tiempo.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,3,'Which sentence expresses a belief naturally?','["I''m believing your explanation.","I am believe your explanation.","I believe your explanation.","I believing your explanation."]'::jsonb,'https://jnfz92.github.io/post/stative-verbs.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Believe es normalmente un verbo de estado.
B) Am believe es gramaticalmente incorrecto.
C) Present Simple describe creencias.
D) Falta auxiliar y el gerundio no corresponde.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,4,'Which sentence uses have as an action?','["She is having three sisters.","She is having a bicycle.","She is having a good memory.","She is having breakfast."]'::jsonb,'https://jnfz92.github.io/post/stative-verbs.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Familia: have es estado, no acción.
B) Posesión: se usa has.
C) Poseer buena memoria es estado.
D) Having breakfast expresa una acción.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,5,'He suggested ______ a short break.','["taking","to take","take","took"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Suggest + gerundio es correcto.
B) Suggest no lleva to-infinitive así.
C) Falta el gerundio.
D) Took es pasado, no gerundio.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,6,'We hope ______ our English this year.','["improving","to improve","improve","improved"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Hope no usa gerundio directo aquí.
B) Hope + to-infinitive es correcto.
C) Falta to.
D) Improved no encaja tras hope.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,7,'I remember ______ that museum when I was ten.','["to visit","visit","visiting","visited"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) To visit es recordar una tarea pendiente.
B) Visit requiere otra estructura.
C) Visiting recuerda una experiencia pasada.
D) Visited no sigue directamente a remember.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,8,'I have ______ tried scuba diving. (Nunca)','["not never","yet","no","never"]'::jsonb,'https://jnfz92.github.io/post/present-perfect-never-yet.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Doble negación incorrecta.
