D) Never indica experiencia nunca vivida.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,9,'Have you sent the confirmation email ______?','["yet","never","still","already not"]'::jsonb,'https://jnfz92.github.io/post/present-perfect-never-yet.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Yet al final pregunta por algo esperado.
B) Never cambiaría el significado.
