D) Already not es un orden incorrecto.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,10,'______ the journey was long, we enjoyed the trip.','["Despite","Although","In spite of","However"]'::jsonb,'https://jnfz92.github.io/post/linking-words-of-contrast.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Despite necesita nombre o -ing.
B) Although introduce sujeto y verbo.
C) In spite of necesita nombre o -ing.
D) However requiere otra puntuación y estructura.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,11,'My brother prefers basketball, ______ I prefer football.','["despite","nevertheless","whereas","in spite of"]'::jsonb,'https://jnfz92.github.io/post/linking-words-of-contrast.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Despite no une dos cláusulas así.
B) Nevertheless exige otra puntuación.
C) Whereas contrasta dos preferencias.
D) In spite of requiere nombre o -ing.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,12,'______ being nervous, she gave a great presentation.','["Although","Even though","Despite of","Despite"]'::jsonb,'https://jnfz92.github.io/post/linking-words-of-contrast.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Although requiere una oración completa.
B) Even though requiere oración completa.
C) Despite of es incorrecto.
D) Despite + gerundio es correcto.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,13,'The taxi has stopped. Please ______ the car.','["get out of","get off","get up","get in"]'::jsonb,'https://jnfz92.github.io/post/get-phrasal-verbs.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Get out of se usa para salir del coche.
B) Get off se usa para bus o tren.
C) Get up significa levantarse.
D) Get in significa entrar.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,14,'Your dentist appointment is confirmed for 10 tomorrow.','["I had seen my dentist at ten.","I''m seeing my dentist at ten.","I have seen my dentist at ten.","I was seeing my dentist at ten."]'::jsonb,'https://jnfz92.github.io/post/future-going-to-present-continuous.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Past Perfect refiere al pasado.
B) Present Continuous indica plan concertado.
C) Present Perfect no indica cita futura.
D) Past Continuous refiere al pasado.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,15,'______ from houses can contaminate rivers. (Aguas residuales)','["Noise pollution","Renewable energy","Sewage","Emissions"]'::jsonb,'https://jnfz92.github.io/post/pollution-environment-vocabulary.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Es contaminación acústica.
B) Es energía renovable.
C) Sewage significa aguas residuales.
D) Emissions son emisiones, no aguas residuales.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,16,'Don''t leave ______ on the beach. (Basura tirada)','["recycling","landfill","renewable energy","litter"]'::jsonb,'https://jnfz92.github.io/post/pollution-environment-vocabulary.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Recycling es reciclaje.
B) Landfill es vertedero.
C) Renewable energy es energía renovable.
D) Litter es basura tirada.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,17,'To find a specific date quickly, use ______.','["scanning","skimming","memorising everything","reading only the title"]'::jsonb,'https://jnfz92.github.io/post/skimming-scanning-reading.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Scanning busca datos concretos.
B) Skimming capta la idea general.
C) Memorizar todo no es la técnica indicada.
D) El título no suele dar la fecha.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,18,'Choose the opposite of possible.','["unpossible","impossible","dispossible","mispossible"]'::jsonb,'https://jnfz92.github.io/post/negative-prefixes.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Unpossible no es forma estándar.
B) Impossible es el antónimo correcto.
C) Dispossible no existe en uso estándar.
D) Mispossible no es palabra estándar.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,19,'The shop ______ tonight. (Posibilidad negativa)','["might not to open","might doesn''t open","might not open","might not opens"]'::jsonb,'https://jnfz92.github.io/post/modal-verb-might.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Tras might no se usa to.
B) Might no combina con doesn''t.
C) Might not + verbo base es correcto.
D) Tras might no se añade -s.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,20,'Could you give me ______ information?','["several","a few","many","some"]'::jsonb,'https://jnfz92.github.io/post/countable-uncountable-nouns.html' from public.examenes where codigo='EE-2026-10-12-004' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Several exige plural contable.
B) A few exige plural contable.
C) Many exige plural contable.
D) Some sirve con incontable information.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
insert into public.examenes(codigo,titulo,fecha,nivel,descripcion,publicado) values('EE-2026-10-13-005','Examen diario 005','2026-10-13','B1-B2','20 preguntas',true) on conflict(codigo) do update set titulo=excluded.titulo,publicado=true;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,1,'By the time the lecture began, Marta ______ for two hours.','["had been studying","has been studying","was study","had been study"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-pasado-en-ingles.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Correcta: had been + -ing destaca la duración anterior a un momento pasado.
B) Has been studying conecta con el presente, no con el comienzo pasado de la clase.
C) Was study es incorrecto; sería was studying y no subrayaría aquí la duración anterior.
D) Had been study es incorrecto; después de been se requiere studying.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,2,'This time tomorrow, we ______ to Madrid.','["have travelled","will be travelling","will have travelled","travelled"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-futuro-en-ingles.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Present Perfect no expresa una acción en curso a esta hora de mañana.
B) Correcta: Future Continuous expresa una acción en progreso en un momento futuro.
C) Future Perfect indica una acción terminada antes de un momento futuro, no en curso.
D) Past Simple se refiere al pasado y no encaja con tomorrow.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,3,'By next June, she ______ at this company for ten years.','["will working","has been worked","will have been working","will have working"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-futuro-en-ingles.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Will working es incorrecto: falta be para formar el continuo.
B) Has been worked no expresa la duración futura de la actividad.
C) Correcta: Future Perfect Continuous destaca duración hasta una fecha futura.
D) Will have working es incorrecto; falta been.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,4,'According to the official timetable, the train ______ at 7:15 tomorrow.','["will leaving","is leave","has left","leaves"]'::jsonb,'https://jnfz92.github.io/post/todos-los-tiempos-de-futuro-en-ingles.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Will leaving es incorrecto; will requiere verbo base.
B) Is leave es incorrecto; el continuo sería is leaving.
C) Has left se refiere a una acción ya terminada, no a mañana.
D) Correcta: Present Simple se usa con horarios oficiales.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,5,'Ana said, “I am leaving now.” Report this later using the usual backshift.','["Ana said that she was leaving then.","Ana said that she is leave now.","Ana said that she had leaving yesterday.","Ana said that she leaving then."]'::jsonb,'https://jnfz92.github.io/post/direct-reported-speech.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Correcta: am leaving suele pasar a was leaving y now a then.
B) Is leave es incorrecto: falta -ing y no se aplica el cambio de tiempo.
C) Had leaving es incorrecto; had requiere participio.
D) She leaving carece del auxiliar was.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,6,'Choose the natural sentence to express a permanent preference.','["I am preferring tea.","I prefer tea.","I am prefer tea.","I preferring tea."]'::jsonb,'https://jnfz92.github.io/post/stative-verbs.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Prefer suele ser un verbo de estado y no se usa en continuo para preferencias generales.
B) Correcta: Present Simple expresa preferencias generales.
C) Am prefer no es una forma verbal correcta.
D) I preferring carece de auxiliar y no es una oración completa.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,7,'They kept ______ English even during their holidays.','["to practise","practise","practising","practised"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Keep no suele ir seguido de to + infinitivo con este sentido.
B) Keep exige gerundio para indicar continuación, no verbo base.
C) Correcta: keep + -ing expresa seguir haciendo algo.
D) Practised es pasado o participio, no gerundio.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,8,'I remember ______ her at the conference last year. It was a great conversation.','["to meet","meet","met","meeting"]'::jsonb,'https://jnfz92.github.io/post/gerund-infinitive.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Remember to meet significa acordarse de hacer algo, no recordar una experiencia.
B) Meet en forma base no va directamente tras remember con este sentido.
C) Met es pasado, pero remember requiere -ing para recordar una experiencia.
D) Correcta: remember meeting indica recuerdo de una experiencia anterior.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,9,'Every summer, our family ______ our grandparents in the countryside. (repeated past action)','["would visit","would visiting","would visited","would to visit"]'::jsonb,'https://jnfz92.github.io/post/used-to-would-be-used-to-get-used-to.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Correcta: would + verbo base expresa acciones habituales del pasado.
B) Would visiting es incorrecto; el modal requiere verbo base.
C) Would visited es incorrecto; no se usa pasado tras would.
D) Would to visit es incorrecto; no se añade to.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,10,'I''m not used to ______ so early on Saturdays.','["get up","getting up","got up","gets up"]'::jsonb,'https://jnfz92.github.io/post/used-to-would-be-used-to-get-used-to.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Be used to requiere sustantivo o -ing, no verbo base.
B) Correcta: be used to + -ing significa estar acostumbrado.
C) Got up es pasado, no el gerundio requerido.
D) Gets up es tercera persona presente, no gerundio.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,11,'______ the fact that it was freezing, they went swimming.','["Despite of","Even though","Despite","Whereas"]'::jsonb,'https://jnfz92.github.io/post/despite-vs-in-spite-of.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Despite of es incorrecto; se usa despite o in spite of.
B) Even though introduce una oración completa y no encaja delante de the fact that aquí.
C) Correcta: despite the fact that + oración introduce un contraste.
D) Whereas no se usa con the fact that en esta estructura.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,12,'I studied hard. ______, I didn''t pass the exam.','["Although","Despite","Whereas","Nevertheless"]'::jsonb,'https://jnfz92.github.io/post/linking-words-of-contrast.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Although requiere una oración subordinada, no funciona solo como conector aquí.
B) Despite requiere un sustantivo o -ing, no aparece aislado así.
C) Whereas conecta oraciones contrastadas, no funciona como adverbio independiente aquí.
D) Correcta: Nevertheless, con coma, contrasta dos oraciones.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,13,'I haven''t received the parcel ______.','["yet","never","already not","since"]'::jsonb,'https://jnfz92.github.io/post/present-perfect-never-yet.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Correcta: yet al final de negativa Present Perfect significa todavía no.
B) Never después de haven''t forma doble negación no estándar.
C) Already not no es la colocación natural en esta frase.
D) Since necesita una referencia temporal, no puede quedar solo.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,14,'She ______ in Seville since 2021, and she still lives there.','["lived","has lived","had live","is live"]'::jsonb,'https://jnfz92.github.io/post/present-perfect-vs-past-simple.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) Past Simple no indica naturalmente continuidad hasta hoy con since.
B) Correcta: Present Perfect con since señala inicio pasado y continuidad actual.
C) Had live es incorrecto; sería had lived y requeriría otro momento pasado.
D) Is live es incorrecto; podría decirse lives o is living en otro contexto.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,15,'The museum ______ be open on Monday; I''m not sure.','["might to","might opens","might","mighting"]'::jsonb,'https://jnfz92.github.io/post/modal-verb-might.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) Might no lleva to antes del infinitivo.
B) Might opens es incorrecto: no se añade -s después de un modal.
C) Correcta: might be expresa una posibilidad incierta.
D) Mighting no es una forma válida del modal.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,16,'We need ______ information before making a decision.','["many","several","a few","some"]'::jsonb,'https://jnfz92.github.io/post/countable-uncountable-nouns.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) Many requiere plural contable; information es incontable.
B) Several requiere plural contable.
C) A few requiere plural contable.
D) Correcta: some funciona con el incontable information.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,17,'According to ''Protector of the Sea'', roughly how many divers formed the original community?','["About 100","About 12","About 1,500","Only two"]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,0,'A) Correcta: el artículo describe una comunidad inicial de unos 100 buceadores.
B) 12 corresponde a empleados a tiempo completo posteriores.
C) 1.500 es la red posterior de voluntarios.
D) Dos eran los amigos de Swietenia, no el número de buceadores.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,18,'How long did it take for that divers'' community to become Divers Clean Action (DCA)?','["Ten years","Two years","One month","Twenty years"]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,1,'A) El texto no indica diez años.
B) Correcta: dos años después la comunidad pasó a ser una fundación.
C) No fue un mes según el artículo.
D) El texto no dice veinte años.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,19,'How many volunteers are in DCA''s network according to the article?','["12","100","1,500","15,000"]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,2,'A) 12 es el número de empleados a tiempo completo.
B) 100 es la cifra aproximada de buceadores iniciales.
C) Correcta: el artículo menciona 1.500 voluntarios.
D) 15.000 es diez veces la cifra del texto.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
with p as (insert into public.preguntas(examen_id,orden,enunciado,opciones,fuente_url) select id,20,'Why did Swietenia decide to study environmental engineering?','["She wanted to become a pilot.","She wanted to work in a language school.","She was told the sea had become cleaner.","She remained concerned about the marine environment."]'::jsonb,'https://jnfz92.github.io/post/protector-of-the-sea-vocabulary-tenses.html' from public.examenes where codigo='EE-2026-10-13-005' on conflict(examen_id,orden) do update set enunciado=excluded.enunciado,opciones=excluded.opciones,fuente_url=excluded.fuente_url returning id) insert into private.soluciones(pregunta_id,respuesta_correcta,explicacion) select id,3,'A) El texto no habla de una carrera en aviación.
B) No se menciona ninguna escuela de idiomas.
C) Swietenia vio deterioro del mar, no una mejora.
D) Correcta: su preocupación por el medio marino motivó sus estudios.' from p on conflict(pregunta_id) do update set respuesta_correcta=excluded.respuesta_correcta,explicacion=excluded.explicacion;
commit;
